function validate([sensor1, sensor2]) {
  if (!Array.isArray(sensor1) || !Array.isArray(sensor2)) return 'Both sensors need a list of readings.';
  if (sensor1.length !== sensor2.length) return 'Both sensors must have the same number of readings.';
  const n = sensor1.length;
  if (n < 1 || n > 100) return 'Each sensor needs 1 to 100 readings.';
  if ([...sensor1, ...sensor2].some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each reading is an integer from 1 to 100.';
  if (sensor1.every((v, i) => v === sensor2[i])) return null;
  const explains = (bad, good) => {
    for (let k = 0; k < n; k++) {
      let same = true;
      for (let j = 0; j < n - 1 && same; j++) if (bad[j] !== good[j < k ? j : j + 1]) same = false;
      if (same && bad[n - 1] !== good[k]) return true;
    }
    return false;
  };
  if (!explains(sensor1, sensor2) && !explains(sensor2, sensor1)) return 'The readings must match, or one sensor must have lost exactly one reading.';
  return null;
}

