    i++;
  }
  let firstFaulty = true;
  let secondFaulty = true;
  for (let j = i; j < n - 1; j++) {
    if (sensor1[j] !== sensor2[j + 1]) {
      firstFaulty = false;
    }
    if (sensor2[j] !== sensor1[j + 1]) {
      secondFaulty = false;
    }
  }
  if (firstFaulty === secondFaulty) {
    return -1;
  }
  return firstFaulty ? 1 : 2;
}

