function badSensor(sensor1, sensor2) {
  const n = sensor1.length;
  // Can "bad" be produced from "good" by losing one reading and appending a different value?
  const explains = (bad, good) => {
    for (let k = 0; k < n; k++) {
      const kept = good.slice(0, k).concat(good.slice(k + 1));
      let same = true;
      for (let j = 0; j < n - 1; j++) if (bad[j] !== kept[j]) same = false;
      if (same && bad[n - 1] !== good[k]) return true;
    }
    return false;
  };
  const one = explains(sensor1, sensor2);
  const two = explains(sensor2, sensor1);
  if (one && !two) return 1;
  if (two && !one) return 2;
  return -1;
}

