function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  const top = size === 'large' ? (rand() < 0.5 ? 100 : 3) : (rand() < 0.5 ? 2 : 4);
  const pick = () => 1 + Math.floor(rand() * top);
  const truth = Array.from({ length: n }, pick);
  const mode = Math.floor(rand() * 5);
  if (mode === 0) return [truth, truth.slice()];
  // Lean towards an early lost reading on large inputs so the shifted part is long.
  const k = size === 'large' && rand() < 0.5 ? Math.floor(rand() * 10) : Math.floor(rand() * n);
  const broken = truth.slice(0, k).concat(truth.slice(k + 1));
  let last;
  do { last = pick(); } while (last === truth[k]);
  broken.push(last);
  return mode <= 2 ? [broken, truth] : [truth, broken];
}
